/**
 * The curated colour themes (docs/notes/theme-engine-2-engine.md). catalog.json and
 * themes.css are generated by themes/convert.ts (`pnpm run themes`) and committed; a
 * theme is applied by setting `data-theme` on <html> (lib/theme.ts), which selects its
 * block in themes.css. `vars` are the same values, for previews that set them inline.
 */
import catalog from "./catalog.json";

export type ThemeScheme = "light" | "dark";

export interface Theme {
  /** The `data-theme` value. */
  readonly id: string;
  readonly name: string;
  /** Fixed per theme, from its background's lightness. */
  readonly scheme: ThemeScheme;
  /** The light/dark sibling (Catppuccin Mocha and Latte, ...). */
  readonly pair?: string;
  /** Upstream project and the Ghostty file it was converted from. */
  readonly source: string;
  /** Every colour variable index.css declares plus thread.css's syntax colours, all `#rrggbb`. */
  readonly vars: Readonly<Record<string, string>>;
}

export const themes: readonly Theme[] = catalog as Theme[];

export const themeById: ReadonlyMap<string, Theme> = new Map(themes.map((t) => [t.id, t]));

export { DEFAULT_DARK, DEFAULT_LIGHT } from "./defaults";

/** The themes that can fill a scheme's slot, in catalog order (Catppuccin first). */
export function themesFor(scheme: ThemeScheme): readonly Theme[] {
  return themes.filter((t) => t.scheme === scheme);
}
